const N = 100000;
const REPS = 100;
const raw = Array.from({length: N}, () => (Math.random() * 256) | 0);
function thresholdSum(a) {
  let sum = 0;
  for (let r = 0; r < REPS; r++) {
    for (let i = 0; i < a.length; i++) {
      if (a[i] >= 128) sum += a[i];
    }
  }
  return sum;
}
const unsorted = raw.slice();
const sorted = raw.slice().sort((x, y) => x - y);
let t0 = performance.now();
thresholdSum(unsorted);
const tUnsorted = performance.now() - t0;
t0 = performance.now();
thresholdSum(sorted);
const tSorted = performance.now() - t0;
console.log('unsorted ms:', tUnsorted.toFixed(1));
console.log('sorted ms:', tSorted.toFixed(1));
console.log('sorted faster:', tSorted < tUnsorted);

